import * as Plot from "@observablehq/plot";
import { domainOf, type KeysOfType, maxOf, minOf, readLabel, readNumber } from "../render/data.js";
import { type FigureOptions, figure, type SeriesColor, validateFigure } from "../render/figure.js";
import { keyed, renderPlot } from "../render/plot.js";
import { planSeries } from "../render/series.js";
import { type GeometricSummary, geometricSummary } from "./stats.js";

/** A serial dilution series: the first dilution and the factor between steps. */
export interface DilutionSeries {
  /** The reciprocal of the first dilution tested, e.g. 10 for 1:10. */
  readonly start: number;
  /** The factor between steps, e.g. 2 for two-fold or 10 for ten-fold dilutions. */
  readonly factor: number;
}

/** Options for {@link titerPlot}. */
export interface TiterPlotOptions<T extends object> extends FigureOptions {
  readonly data: readonly T[];
  /** The field naming the group each sample belongs to: a cohort, a timepoint, a vaccine arm. */
  readonly group: KeysOfType<T, string | number>;
  /**
   * The field holding each sample's titer as a reciprocal dilution (40 for 1:40). Values below
   * the limit of detection are shown at half the limit, hollow, as is conventional.
   */
  readonly titer: KeysOfType<T, number>;
  /** The dilution series the assay used, which sets the axis ticks (default 1:10, two-fold). */
  readonly dilution?: DilutionSeries;
  /** The limit of detection as a reciprocal dilution (default: the series start). */
  readonly limitOfDetection?: number;
  /** Groups in display order. */
  readonly groupDomain?: readonly (string | number)[];
  /** Color each group as its own series (default), or all in the first series color. */
  readonly colorByGroup?: boolean;
  readonly colors?: Readonly<Record<string, SeriesColor>>;
  /** Tick labels as ratios ("1:40", default) or reciprocal titers ("40"). */
  readonly tickLabels?: "ratio" | "reciprocal";
  readonly groupLabel?: string | null;
  readonly titerLabel?: string | null;
}

interface Sample {
  readonly key: string;
  readonly group: string;
  readonly groupIndex: number;
  readonly titer: number;
  readonly plotted: number;
  readonly belowLimit: boolean;
  offset: number;
}

const KIND = "titerPlot";

const formatTiter = (value: number): string =>
  value >= 100 ? String(Math.round(value)) : String(Math.round(value * 10) / 10);

/**
 * Antibody or viral titers by group on a log dilution axis: every sample as a point, the
 * geometric mean titer (GMT) with its 95% confidence interval, and the assay's limit of
 * detection. Identical titers are spread side by side rather than drawn on top of each other,
 * so the number of samples at each dilution is visible. The GMT counts a value below the limit
 * of detection as half the limit, the usual convention, and the data table says how many there were.
 *
 * @example
 * titerPlot({
 *   data: sera,
 *   group: "timepoint",
 *   titer: "hai",
 *   dilution: { start: 10, factor: 2 },
 *   alt: "HAI titers rose from a GMT of 14 before vaccination to 160 at day 28 ...",
 * });
 */
export function titerPlot<T extends object>(options: TiterPlotOptions<T>): string {
  const { data, group, titer } = options;
  validateFigure(KIND, options);
  if (data.length === 0) throw new Error(`${KIND}: data is empty`);
  const dilution = options.dilution ?? { start: 10, factor: 2 };
  if (!(dilution.start > 0) || !(dilution.factor > 1)) {
    throw new Error(`${KIND}: dilution needs start above 0 and factor above 1`);
  }
  const lod = options.limitOfDetection ?? dilution.start;
  const groupLabel = options.groupLabel === undefined ? group : options.groupLabel;
  const titerLabel = options.titerLabel === undefined ? "Titer" : options.titerLabel;
  const asRatio = (options.tickLabels ?? "ratio") === "ratio";
  const tick = (v: number): string => (asRatio ? `1:${formatTiter(v)}` : formatTiter(v));

  const rawGroups = data.map((row, i) => readLabel(KIND, row, group, i));
  const groups = domainOf(KIND, group, rawGroups, options.groupDomain?.map(String));
  const samples = data.map((row, i): Sample => {
    const value = readNumber(KIND, row, titer, i);
    if (value <= 0)
      throw new Error(`${KIND}: row ${i + 1} titer is ${value}; titers are positive reciprocals`);
    const g = rawGroups[i] as string;
    const belowLimit = value < lod;
    return {
      key: String(i),
      group: g,
      groupIndex: groups.indexOf(g),
      titer: value,
      plotted: belowLimit ? lod / 2 : value,
      belowLimit,
      offset: 0,
    };
  });

  // Spread samples that share a group and titer across the group's width, centered.
  const stacks = new Map<string, Sample[]>();
  for (const s of samples) {
    const id = `${s.group}|${s.plotted}`;
    stacks.set(id, [...(stacks.get(id) ?? []), s]);
  }
  const widest = maxOf([...stacks.values()].map((s) => s.length));
  const spacing = Math.min(0.08, 0.7 / Math.max(1, widest - 1));
  for (const stack of stacks.values()) {
    stack.forEach((s, k) => {
      s.offset = (k - (stack.length - 1) / 2) * spacing;
    });
  }

  // Keyboard order within a group: lowest titer first, then left to right.
  const withinGroup = new Map<Sample, number>();
  for (const g of groups) {
    samples
      .filter((s) => s.group === g)
      .sort((a, b) => a.plotted - b.plotted || a.offset - b.offset)
      .forEach((s, i) => {
        withinGroup.set(s, i);
      });
  }
  const summaries = new Map<string, GeometricSummary>(
    groups.map((g) => [
      g,
      geometricSummary(samples.filter((s) => s.group === g).map((s) => s.plotted)),
    ]),
  );
  const colorByGroup = options.colorByGroup ?? true;
  const plan = planSeries(KIND, colorByGroup ? groups : ["Samples"], options.colors);
  const colorOf = (s: Sample): string => (colorByGroup ? s.group : "Samples");

  const all = samples.map((s) => s.plotted);
  const top = Math.max(maxOf(all), lod);
  const ticks: number[] = [];
  for (let v = dilution.start; v <= top * dilution.factor; v *= dilution.factor) {
    ticks.push(v);
    // A step this fine is not a dilution series, and would draw thousands of ticks (F15).
    if (ticks.length > 40) {
      throw new Error(
        `${KIND}: dilution factor ${dilution.factor} needs over 40 steps from ${dilution.start} to ${top}`,
      );
    }
  }
  if (lod / 2 < dilution.start) ticks.unshift(lod / 2);

  const summaryRows = groups.map((g, i) => ({ g, i, s: summaries.get(g) as GeometricSummary }));
  const intervalRows = summaryRows.filter(
    (r) => r.s.lower !== undefined && r.s.upper !== undefined,
  );
  const describe = (s: Sample): string =>
    `${groupLabel ?? group} ${s.group}: ${s.belowLimit ? `below the limit of detection (<${tick(lod)})` : tick(s.titer)}`;

  const marks: Plot.Markish[] = [
    Plot.ruleY([lod], { strokeDasharray: "4,3" }),
    Plot.text([lod], {
      y: (d: number) => d,
      text: () => "LOD",
      frameAnchor: "right",
      textAnchor: "end",
      dy: -6,
    }),
    Plot.link(intervalRows, {
      x1: (r: (typeof intervalRows)[number]) => r.i,
      x2: (r: (typeof intervalRows)[number]) => r.i,
      y1: (r: (typeof intervalRows)[number]) => r.s.lower ?? r.s.mean,
      y2: (r: (typeof intervalRows)[number]) => r.s.upper ?? r.s.mean,
      stroke: "var(--enarratio-text)",
      strokeWidth: 1.5,
    }),
    Plot.link(summaryRows, {
      x1: (r: (typeof summaryRows)[number]) => r.i - 0.28,
      x2: (r: (typeof summaryRows)[number]) => r.i + 0.28,
      y1: (r: (typeof summaryRows)[number]) => r.s.mean,
      y2: (r: (typeof summaryRows)[number]) => r.s.mean,
      stroke: "var(--enarratio-text)",
      strokeWidth: 2.5,
    }),
    Plot.dot(samples, {
      x: (s: Sample) => s.groupIndex + s.offset,
      y: "plotted",
      r: 4,
      stroke: colorOf,
      fill: colorOf,
      strokeWidth: 1.5,
      fillOpacity: 0.85,
      title: describe,
      render: keyed(
        samples,
        (s) => ({
          key: s.key,
          filter: { field: group, value: s.group },
          column: s.groupIndex,
          row: withinGroup.get(s) ?? 0,
          x: s.group,
          series: s.group,
        }),
        // Below the limit of detection is hollow: a shape difference, not only a color one.
        (el, s) => {
          if (s.belowLimit) el.setAttribute("fill", "var(--enarratio-background)");
        },
      ),
    }),
  ];

  const { svg } = renderPlot(
    {
      width: options.width ?? 640,
      height: options.height ?? 360,
      marginTop: 20,
      marginLeft: titerLabel === null ? 56 : 72,
      marginBottom: 44,
      x: {
        type: "linear",
        domain: [-0.5, groups.length - 0.5],
        ticks: groups.map((_, i) => i),
        tickFormat: (i: number) => groups[i] ?? "",
        label: groupLabel,
        labelAnchor: "center",
        labelArrow: "none",
      },
      y: {
        type: "log",
        base: dilution.factor,
        domain: [minOf(ticks), maxOf(ticks)],
        ticks,
        tickFormat: tick,
        label: titerLabel,
        labelAnchor: "center",
        labelArrow: "none",
        grid: true,
      },
      color: { domain: plan.names, range: [...plan.range] },
      marks,
    },
    options.alt,
  );

  return figure(options, {
    kind: "titer",
    svg,
    legend: [],
    slotColors: plan.slotColors,
    table: {
      columns: [groupLabel ?? group, "n", "GMT", "95% CI", "Below LOD", "Titers"],
      rows: summaryRows.map(({ g, s }) => {
        const members = samples.filter((x) => x.group === g);
        return [
          g,
          String(s.n),
          formatTiter(s.mean),
          s.lower === undefined || s.upper === undefined
            ? ""
            : `${formatTiter(s.lower)} to ${formatTiter(s.upper)}`,
          String(members.filter((x) => x.belowLimit).length),
          members
            .map((x) => (x.belowLimit ? `<${formatTiter(lod)}` : formatTiter(x.titer)))
            .join(", "),
        ];
      }),
    },
  });
}

test/render.test.ts.source:
/**
 * Rendering tests: the server output of every gallery example, compared with a stored copy, so any
 * change to the markup a site receives is seen in review. Update with `npx vitest run -u` and read
 * the diff before committing it.
 */
import { readdirSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import { parse } from "./helpers.js";

const examplesDir = resolve(import.meta.dirname, "..", "examples");
const examples = readdirSync(examplesDir).filter((f) => f.endsWith(".ts"));

describe("server rendering", () => {
  it.each(examples)("%s renders the stored markup", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    await expect(module.default).toMatchFileSnapshot(
      join("__snapshots__", "render", `${basename(file, ".ts")}.html`),
    );
  });

  it.each(examples)("%s is well-formed and every svg is named", async (file) => {
    const module = (await import(pathToFileURL(join(examplesDir, file)).href)) as {
      default: string;
    };
    const root = parse(`<div>${module.default}</div>`);
    const svgs = [...root.querySelectorAll("svg")];
    expect(svgs.length).toBeGreaterThan(0);
    for (const svg of svgs) {
      // One image, or a named group when its marks are links.
      expect(["img", "group"]).toContain(svg.getAttribute("role"));
      expect((svg.getAttribute("aria-label") ?? "").length).toBeGreaterThan(0);
    }
    for (const fig of root.querySelectorAll("figure")) {
      expect(fig.hasAttribute("aria-label")).toBe(false);
      expect(fig.querySelector("table")).not.toBeNull();
    }
    // No inline event handlers or scripts can reach the markup.
    expect(module.default).not.toMatch(/<script|\son[a-z]+=/i);
  });
});

test/bar.test.ts.source:
import { describe, expect, it } from "vitest";
import { barChart } from "../src/plot/index.js";
import { keyedMarks, parse } from "./helpers.js";

const entries = [
  { year: 2022, type: "Publications" },
  { year: 2022, type: "Talks" },
  { year: 2023, type: "Publications" },
  { year: 2024, type: "Grants" },
  { year: 2024, type: "Publications" },
  { year: 2024, type: "Publications" },
];

describe("barChart", () => {
  it("counts rows per category and series when y is omitted", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", alt: "Entries by year" }),
    );
    const marks = keyedMarks(fig);
    expect(marks.map((m) => JSON.parse(m.getAttribute("data-enarratio-key") ?? ""))).toEqual([
      ["2022", "Publications"],
      ["2022", "Talks"],
      ["2023", "Publications"],
      ["2024", "Publications"],
      ["2024", "Grants"],
    ]);
    expect(marks[3]?.querySelector("title")?.textContent).toBe("year 2024, Publications: 2");
  });

  it("names the SVG, not the figure, and keeps caption and table outside role=img", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        alt: "Entries by year",
        caption: "Source: CV",
      }),
    );
    expect(fig.tagName.toLowerCase()).toBe("figure");
    expect(fig.hasAttribute("aria-label")).toBe(false);
    const svg = fig.querySelector("svg");
    expect(svg?.getAttribute("role")).toBe("img");
    expect(svg?.getAttribute("aria-label")).toBe("Entries by year");
    expect(svg?.querySelector("figcaption, table")).toBeNull();
    expect(fig.querySelector("figcaption")?.textContent).toBe("Source: CV");
  });

  it("emits an equivalent data table, zero-filling counts", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const rows = [...fig.querySelectorAll("tbody tr")].map((tr) =>
      [...tr.children].map((c) => c.textContent),
    );
    expect(rows).toEqual([
      ["2022", "1", "1", "0"],
      ["2023", "1", "0", "0"],
      ["2024", "2", "0", "1"],
    ]);
    expect([...fig.querySelectorAll("thead th")].map((th) => th.textContent)).toEqual([
      "year",
      "Publications",
      "Talks",
      "Grants",
    ]);
  });

  it("colors series by palette slot and lists them in a legend", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const talks = keyedMarks(fig).find((m) => m.getAttribute("data-enarratio-series") === "Talks");
    expect(talks?.getAttribute("fill")).toBe("var(--enarratio-series-2)");
    const legend = [...fig.querySelectorAll(".enarratio-legend li")];
    expect(legend.map((li) => [li.textContent, li.getAttribute("data-slot")])).toEqual([
      ["Publications", "1"],
      ["Talks", "2"],
      ["Grants", "3"],
    ]);
  });

  it("carries filter attributes for the enhancement layer", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const mark = keyedMarks(fig)[0];
    expect(mark?.getAttribute("data-enarratio-field")).toBe("type");
    expect(mark?.getAttribute("data-enarratio-value")).toBe("Publications");
    expect(mark?.getAttribute("data-enarratio-x")).toBe("2022");
  });

  it("shows empty categories and a fixed series order when given", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        xDomain: [2021, 2022, 2023, 2024],
        seriesDomain: ["Grants", "Publications", "Talks"],
        alt: "a",
      }),
    );
    expect([...fig.querySelectorAll("tbody th")].map((th) => th.textContent)).toEqual([
      "2021",
      "2022",
      "2023",
      "2024",
    ]);
    expect(fig.querySelector(".enarratio-legend li")?.textContent).toBe("Grants");
  });

  it("uses whole-number ticks for counts", () => {
    const fig = parse(barChart({ data: entries, x: "year", series: "type", alt: "a" }));
    const ticks = [...fig.querySelectorAll('[data-enarratio-mark="y-axis tick label"] text')].map(
      (t) => t.textContent,
    );
    expect(ticks).toEqual(["0", "1", "2", "3"]);
  });

  it("draws one series with given values, horizontal, and filters by category", () => {
    const fig = parse(
      barChart({
        data: [
          { lab: "A", n: 3 },
          { lab: "B", n: 5 },
        ],
        x: "lab",
        y: "n",
        orientation: "horizontal",
        alt: "a",
      }),
    );
    expect(fig.getAttribute("data-enarratio-orientation")).toBe("horizontal");
    expect(fig.querySelector(".enarratio-legend")).toBeNull();
    expect(keyedMarks(fig).map((m) => m.getAttribute("data-enarratio-field"))).toEqual([
      "lab",
      "lab",
    ]);
  });

  it("groups series side by side", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", layout: "grouped", alt: "a" }),
    );
    expect(keyedMarks(fig)).toHaveLength(5);
  });

  it("applies color overrides to the figure's slot", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        colors: { Talks: { light: "#112233", dark: "#aabbcc" } },
        alt: "a",
      }),
    );
    expect(fig.getAttribute("style")).toBe("--enarratio-series-2: light-dark(#112233, #aabbcc)");
  });

  it("escapes caller text", () => {
    const markup = barChart({
      data: [{ k: "<b>", v: 1 }],
      x: "k",
      y: "v",
      title: 'A "quoted" <title>',
      alt: "a & b",
    });
    expect(markup).not.toContain("<b>");
    expect(markup).toContain("A &quot;quoted&quot; &lt;title&gt;");
  });

  it("is deterministic", () => {
    const options = { data: entries, x: "year", series: "type", alt: "a" } as const;
    expect(barChart(options)).toBe(barChart(options));
  });

  it("refuses a missing alt, bad values, unknown color keys and too many series", () => {
    expect(() => barChart({ data: entries, x: "year", alt: "  " })).toThrow(/alt is required/);
    expect(() => barChart({ data: [{ k: "a", v: Number.NaN }], x: "k", y: "v", alt: "a" })).toThrow(
      /row 1 field "v" is NaN/,
    );
    expect(() =>
      barChart({ data: entries, x: "year", series: "type", colors: { Books: "#000" }, alt: "a" }),
    ).toThrow(/"Books", which is not a series/);
    const many = Array.from({ length: 9 }, (_, i) => ({ x: "a", s: `s${i}` }));
    expect(() => barChart({ data: many, x: "x", series: "s", alt: "a" })).toThrow(/9 series/);
    expect(() => barChart({ data: entries, x: "year", xDomain: [2022], alt: "a" })).toThrow(
      /2023" is missing from the year domain/,
    );
    expect(() =>
      barChart({
        data: entries,
        x: "year",
        series: "type",
        colors: { Talks: "url(#x)" },
        alt: "a",
      }),
    ).toThrow(/not an allowed color/);
  });

  it("filters by category when asked, even with series", () => {
    const fig = parse(
      barChart({ data: entries, x: "year", series: "type", filterBy: "x", alt: "a" }),
    );
    const mark = keyedMarks(fig)[0];
    expect(mark?.getAttribute("data-enarratio-field")).toBe("year");
    expect(mark?.getAttribute("data-enarratio-value")).toBe("2022");
  });

  it("makes each bar a link for readers without script", () => {
    const fig = parse(
      barChart({
        data: entries,
        x: "year",
        series: "type",
        href: (y) => `/cv?year=${y}`,
        alt: "a",
      }),
    );
    const marks = keyedMarks(fig);
    expect(marks[0]?.tagName.toLowerCase()).toBe("a");
    expect(marks[0]?.getAttribute("href")).toBe("/cv?year=2022");
    expect(marks[0]?.querySelector("rect title")?.textContent).toBe("year 2022, Publications: 1");
  });

  it("refuses links that are not relative or http(s)", () => {
    for (const bad of ["javascript:alert(1)", " java\tscript:x", "data:text/html,x"]) {
      expect(() => barChart({ data: entries, x: "year", href: () => bad, alt: "a" })).toThrow(
        /not a relative or http\(s\) link/,
      );
    }
    expect(() =>
      barChart({ data: entries, x: "year", href: (y) => `https://example.org/${y}`, alt: "a" }),
    ).not.toThrow();
  });

  it("thins category labels to at most maxXTicks, keeping the first", () => {
    const years = Array.from({ length: 20 }, (_, i) => ({ year: 2000 + i }));
    const fig = parse(barChart({ data: years, x: "year", maxXTicks: 5, alt: "a" }));
    const labels = [...fig.querySelectorAll('[data-enarratio-mark="x-axis tick label"] text')].map(
      (t) => t.textContent,
    );
    expect(labels).toEqual(["2000", "2004", "2008", "2012", "2016"]);
    expect(() => barChart({ data: years, x: "year", maxXTicks: 0, alt: "a" })).toThrow(/maxXTicks/);
  });
});

test/timeline.test.ts.source:
/**
 * The event timeline and the heat strip: the two primitives added in 0.2. Each is checked
 * against the numbers it was given: what is drawn, hovered and listed is the same data.
 */
import { describe, expect, it } from "vitest";
import { heatStrip, type TimelineOptions, timeline } from "../src/index.js";
import { parse } from "./helpers.js";

const events: TimelineOptions["events"] = [
  {
    lane: "Agent A",
    label: "Nightly run",
    status: "ok",
    from: "2026-06-09T01:00:00Z",
    to: "2026-06-09T05:00:00Z",
  },
  {
    lane: "Agent A",
    label: "Retry",
    status: "warning",
    from: "2026-06-09T04:00:00Z",
    to: "2026-06-09T06:00:00Z",
  },
  { lane: "Agent B", label: "Timeout", status: "error", at: "2026-06-09T03:00:00Z" },
  { lane: "Agent B", label: "Heartbeat lost", status: "unknown", at: "2026-06-09T07:00:00Z" },
  { lane: "Agent C", label: "Deploy", status: "ok", at: "2026-06-09T00:00:00Z" },
];
const options = {
  events,
  label: "Agent runs",
  start: "2026-06-09T00:00:00Z",
  end: "2026-06-09T08:00:00Z",
} as const;

describe("timeline", () => {
  const root = parse(timeline(options));
  const svg = root.querySelector("svg");
  const marks = [...root.querySelectorAll('[data-enarratio-mark="event"]')];

  it("is a container holding a named drawing and a plain list", () => {
    expect(root.tagName.toLowerCase()).toBe("div");
    expect(root.getAttribute("data-enarratio")).toBe("timeline");
    expect(svg?.getAttribute("role")).toBe("img");
    expect(svg?.getAttribute("aria-label")).toBe(
      "Agent runs: 5 events in 3 lanes, 2026-06-09 00:00 UTC to 2026-06-09 08:00 UTC; 2 ok, 1 warning, 1 error, 1 unknown.",
    );
    expect(root.querySelectorAll("ol.enarratio-timeline-list li")).toHaveLength(5);
  });

  it("lists every event in time order with its lane, status and time", () => {
    const items = [...root.querySelectorAll("ol li")].map((li) => li.textContent);
    expect(items).toEqual([
      "Agent C: Deploy, ok, 2026-06-09 00:00 UTC",
      "Agent A: Nightly run, ok, from 2026-06-09 01:00 UTC to 2026-06-09 05:00 UTC",
      "Agent B: Timeout, error, 2026-06-09 03:00 UTC",
      "Agent A: Retry, warning, from 2026-06-09 04:00 UTC to 2026-06-09 06:00 UTC",
      "Agent B: Heartbeat lost, unknown, 2026-06-09 07:00 UTC",
    ]);
  });

  it("puts each event at its time on one linear scale", () => {
    // Point events: x is the marker's centre; hour h should sit h/8 of the way along the plot.
    const centre = (mark: Element): number => {
      const shape = mark.querySelector("circle, polygon, rect:last-child");
      if (shape?.localName === "circle") return Number(shape.getAttribute("cx"));
      if (shape?.localName === "rect") return Number(shape.getAttribute("x")) + 4.5;
      const xs = (shape?.getAttribute("points") ?? "")
        .split(" ")
        .map((p) => Number(p.split(",")[0]));
      return xs[0] as number;
    };
    const byLabel = (label: string): Element =>
      marks.find((m) => m.querySelector("title")?.textContent?.includes(label)) as Element;
    const x0 = centre(byLabel("Deploy")); // hour 0
    const x3 = centre(byLabel("Timeout")); // hour 3
    const x7 = centre(byLabel("Heartbeat lost")); // hour 7
    expect((x7 - x0) / 7).toBeCloseTo((x3 - x0) / 3, 1);
  });

  it("draws spans as bars from start to end", () => {
    const run = marks.find((m) => m.querySelector("title")?.textContent?.includes("Nightly run"));
    const bar = run?.querySelector("rect");
    const retry = marks.find((m) => m.querySelector("title")?.textContent?.includes("Retry"));
    const retryBar = retry?.querySelector("rect");
    // 4 hours and 2 hours: widths are in that ratio.
    expect(
      Number(bar?.getAttribute("width")) / Number(retryBar?.getAttribute("width")),
    ).toBeCloseTo(2, 1);
  });

  it("says status by shape as well as color", () => {
    const shape = (label: string): string => {
      const mark = marks.find((m) => m.querySelector("title")?.textContent?.includes(label));
      return [...(mark?.children ?? [])].map((c) => c.localName).at(-1) ?? "";
    };
    expect(shape("Deploy")).toBe("circle");
    expect(shape("Retry")).toBe("polygon");
    expect(shape("Timeout")).toBe("rect");
    const unknown = marks.find((m) => m.querySelector("title")?.textContent?.includes("Heartbeat"));
    expect(unknown?.querySelector("circle")?.getAttribute("stroke-dasharray")).toBeTruthy();
    // And in the theme's status colors.
    expect(marks.find((m) => m.getAttribute("data-status") === "error")?.innerHTML).toContain(
      "--enarratio-status-bad",
    );
  });

  it("stacks overlapping events in a lane instead of drawing them over each other", () => {
    const y = (label: string): number =>
      Number(
        marks
          .find((m) => m.querySelector("title")?.textContent?.includes(label))
          ?.querySelector("rect")
          ?.getAttribute("y"),
      );
    expect(y("Retry")).toBeGreaterThan(y("Nightly run"));
    // Agent B's events do not overlap: one row, so the drawing is shorter than with stacking.
    const flat = parse(
      timeline({ ...options, events: events.filter((e) => e.lane !== "Agent A") }),
    );
    expect(Number(flat.querySelector("svg")?.getAttribute("height"))).toBeLessThan(
      Number(svg?.getAttribute("height")),
    );
  });

  it("draws lanes in the order given, empty ones too", () => {
    const out = parse(
      timeline({ ...options, lanes: ["Agent C", "Agent B", "Agent A", "Agent D"] }),
    );
    const labels = [...out.querySelectorAll("svg > text[text-anchor='end']")].map(
      (t) => t.textContent,
    );
    expect(labels).toEqual(["Agent C", "Agent B", "Agent A", "Agent D"]);
  });

  it("labels the axis with ticks inside the window", () => {
    const labels = [...root.querySelectorAll("svg > text.enarratio-numeric")].map(
      (t) => t.textContent,
    );
    expect(labels.length).toBeGreaterThanOrEqual(3);
    expect(labels.length).toBeLessThanOrEqual(8);
    expect(labels[0]).toMatch(/^\d\d-\d\d$|^\d\d:\d\d$/);
  });

  it("uses calendar ticks for a long window", () => {
    const out = parse(
      timeline({
        label: "Years",
        events: [{ lane: "L", label: "x", status: "ok", at: "2020-03-01" }],
        start: "2020-01-01",
        end: "2026-01-01",
      }),
    );
    const labels = [...out.querySelectorAll("svg > text.enarratio-numeric")].map(
      (t) => t.textContent,
    );
    expect(labels).toContain("2021");
    expect(labels.length).toBeLessThanOrEqual(7);
  });

  it("defaults the window to the events, takes Dates and epoch milliseconds, and formats times", () => {
    const out = parse(
      timeline({
        label: "T",
        events: [
          { lane: "L", label: "a", status: "ok", at: new Date(Date.UTC(2026, 0, 1)) },
          { lane: "L", label: "b", status: "ok", at: Date.UTC(2026, 0, 2) },
        ],
        formatTime: (d) => d.toISOString().slice(0, 10),
      }),
    );
    expect(out.querySelector("svg")?.getAttribute("aria-label")).toBe(
      "T: 2 events in 1 lane, 2026-01-01 to 2026-01-02; 2 ok.",
    );
  });

  it("takes its own text alternative", () => {
    const out = parse(timeline({ ...options, label: undefined as never, alt: "Mine" }));
    expect(out.querySelector("svg")?.getAttribute("aria-label")).toBe("Mine");
  });

  it("clips a span that runs past the window, and keeps its real times in the list", () => {
    const out = parse(
      timeline({
        label: "T",
        start: "2026-06-09T00:00:00Z",
        end: "2026-06-09T08:00:00Z",
        events: [
          {
            lane: "L",
            label: "long",
            status: "ok",
            from: "2026-06-08T20:00:00Z",
            to: "2026-06-10T00:00:00Z",
          },
        ],
      }),
    );
    const bar = out.querySelector('[data-enarratio-mark="event"] rect');
    const width = Number(out.querySelector("svg")?.getAttribute("width"));
    expect(Number(bar?.getAttribute("x")) + Number(bar?.getAttribute("width"))).toBeLessThanOrEqual(
      width,
    );
    expect(out.querySelector("li")?.textContent).toContain("2026-06-08 20:00 UTC");
  });

  it("shortens a long lane name and keeps the whole name as hover text", () => {
    const name = "A very long agent name that cannot fit";
    const out = parse(
      timeline({
        label: "T",
        events: [
          { lane: name, label: "x", status: "ok", at: 1000 },
          { lane: "B", label: "y", status: "ok", at: 5000 },
        ],
      }),
    );
    const text = out.querySelector("svg > text[text-anchor='end']");
    expect(text?.textContent).toContain("…");
    expect(text?.querySelector("title")?.textContent).toBe(name);
  });

  it("refuses what would draw wrongly", () => {
    const bad = (e: unknown, extra: Partial<TimelineOptions> = {}) =>
      timeline({ ...options, events: [e as never], ...extra });
    expect(() => timeline({ ...options, events: [] })).toThrow(/at least one event/);
    expect(() => timeline({ events })).toThrow(/label or alt/);
    expect(() => timeline({ events, label: " " })).toThrow(/label or alt/);
    expect(() => bad({ lane: "A", label: "x", status: "ok" })).toThrow(/needs a time/);
    expect(() => bad({ lane: "A", label: "x", status: "great", at: 1 })).toThrow(/unknown status/);
    expect(() => bad({ lane: "A", label: "x", status: "constructor", at: 1 })).toThrow(
      /unknown status/,
    );
    expect(() => bad({ lane: "A", label: "", status: "ok", at: 1 })).toThrow(/needs a label/);
    expect(() => bad({ lane: "", label: "x", status: "ok", at: 1 })).toThrow(/needs a lane/);
    expect(() => bad({ lane: "A", label: "x", status: "ok", at: "tomorrow" })).toThrow(
      /not a time/,
    );
    expect(() =>
      bad({ lane: "A", label: "x", status: "ok", from: 1, to: 0 }, { start: 0, end: 5 }),
    ).toThrow(/ends before/);
    expect(() =>
      bad({ lane: "A", label: "x", status: "ok", from: 1 }, { start: 0, end: 5 }),
    ).toThrow(/both from and to/);
    expect(() =>
      bad({ lane: "A", label: "x", status: "ok", at: 1, from: 1, to: 2 }, { start: 0, end: 5 }),
    ).toThrow(/both a time/);
    expect(() =>
      bad(
        { lane: "Z", label: "x", status: "ok", at: Date.parse("2026-06-09T01:00Z") },
        { lanes: ["Agent A"] },
      ),
    ).toThrow(/lane "Z"/);
    expect(() =>
      bad({ lane: "Agent A", label: "x", status: "ok", at: Date.parse("2027-01-01") }),
    ).toThrow(/outside the time window/);
    expect(() =>
      timeline({ label: "T", events: [{ lane: "A", label: "x", status: "ok", at: 5 }] }),
    ).toThrow(/no length/);
    expect(() => timeline({ ...options, lanes: ["Agent A", "Agent A"] })).toThrow(/repeated/);
    expect(() => timeline({ ...options, width: 0 })).toThrow(/width/);
  });
});

describe("heatStrip", () => {
  const values = [3, 5, null, 9, 14, 8, 2];
  const root = parse(heatStrip({ values, label: "Requests per hour" }));
  const cells = [...root.querySelectorAll("rect")];

  it("is an svg named by a sentence made from the values", () => {
    expect(root.localName).toBe("svg");
    expect(root.getAttribute("class")).toContain("enarratio-heat-strip");
    expect(root.getAttribute("role")).toBe("img");
    expect(root.getAttribute("aria-label")).toBe(
      "Requests per hour: 7 cells, from 3 to 2; lowest 2, highest 14; 1 with no data.",
    );
  });

  it("colors each cell on the sequential ramp by its value, lowest to highest", () => {
    const fills = cells.map((c) => c.getAttribute("fill"));
    // 2..14 in five equal steps of 2.4: 3 -> 1, 5 -> 2, 9 -> 3, 14 -> 5, 8 -> 3, 2 -> 1.
    expect(fills).toEqual([
      "var(--enarratio-sequential-1)",
      "var(--enarratio-sequential-2)",
      "none",
      "var(--enarratio-sequential-3)",
      "var(--enarratio-sequential-5)",
      "var(--enarratio-sequential-3)",
      "var(--enarratio-sequential-1)",
    ]);
  });

  it("draws a missing value as a dashed outline", () => {
    expect(cells[2]?.getAttribute("stroke-dasharray")).toBe("2,2");
    expect(cells[2]?.querySelector("title")?.textContent).toBe("Cell 3: no data");
  });

  it("puts the value in each cell's hover details", () => {
    expect(cells.map((c) => c.querySelector("title")?.textContent)).toEqual([
      "Cell 1: 3",
      "Cell 2: 5",
      "Cell 3: no data",
      "Cell 4: 9",
      "Cell 5: 14",
      "Cell 6: 8",
      "Cell 7: 2",
    ]);
  });

  it("fills the width with equal cells and has no axis", () => {
    const widths = new Set(cells.map((c) => c.getAttribute("width")));
    expect(widths.size).toBeLessThanOrEqual(2);
    expect(root.querySelector("text, line")).toBeNull();
  });

  it("takes a fixed range, thresholds, cell labels and a formatter", () => {
    const out = parse(
      heatStrip({
        values: [1, 50],
        alt: "Mine",
        min: 0,
        max: 100,
        thresholds: [10, 20, 30, 40],
        cellLabels: ["Mon", "Tue"],
        formatValue: (n) => `${n}%`,
      }),
    );
    expect(out.getAttribute("aria-label")).toBe("Mine");
    expect([...out.querySelectorAll("rect")].map((c) => c.getAttribute("fill"))).toEqual([
      "var(--enarratio-sequential-1)",
      "var(--enarratio-sequential-5)",
    ]);
    expect(out.querySelector("title")?.textContent).toBe("Mon: 1%");
  });

  it("refuses what would draw wrongly", () => {
    const base = { values: [1, 2], label: "x" };
    expect(() => heatStrip({ ...base, values: [] })).toThrow(/at least one value/);
    expect(() => heatStrip({ ...base, values: [null, null] })).toThrow(/every value is empty/);
    expect(() => heatStrip({ ...base, values: [1, Number.NaN] })).toThrow(/not a finite number/);
    expect(() => heatStrip({ values: [1] })).toThrow(/label or alt/);
    expect(() => heatStrip({ ...base, width: -1 })).toThrow(/width/);
    expect(() => heatStrip({ ...base, min: 5, max: 1 })).toThrow(/above max/);
    expect(() => heatStrip({ ...base, thresholds: [1, 1, 2, 3] })).toThrow(/ascend/);
    expect(() => heatStrip({ ...base, cellLabels: ["a"] })).toThrow(/one each/);
  });

  it("copes with flat data", () => {
    const out = parse(heatStrip({ values: [4, 4, 4], label: "Flat" }));
    expect([...out.querySelectorAll("rect")].map((c) => c.getAttribute("fill"))).toEqual(
      Array(3).fill("var(--enarratio-sequential-1)"),
    );
  });
});

